missed = []
used = set()
out = []
for ln in lines:
    if CJK.search(ln):
        replaced = False
        for key, new in REPL:
            if key in used:
                continue
            if key in ln:
                indent = ln[:len(ln) - len(ln.lstrip())]
                ln = indent + new
                used.add(key)
                replaced = True
                break
        if not replaced:
            missed.append(ln)
    out.append(ln)

open(P, 'w', encoding='utf-8').write('\n'.join(out))
print('replaced:', len(used))
if missed:
    print('MISSED LINES:')
    for m in missed:
        print('  ', m[:200])
